let vs = `
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;

void main() { 
  vec3 uPosition = aPosition;
  vec4 positionVec4 = vec4(uPosition, 1.0);

  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;//positionVec4;
  vTexCoord = aTexCoord;
}
`;

let fs = `
#ifdef GL_ES
precision mediump float;
#endif

#define COLOR_N vec3(0.15, 0.34, 0.6)
#define COLOR_T vec3(0.313, 0.816, 0.816)
#define COLOR_M vec3(0.745, 0.118, 0.243)
#define COLOR_K vec3(0.475, 0.404, 0.765)
#define COLOR_H vec3(1.0, 0.776, 0.224)
#define COLOR_S vec3(0.682, 0.706, 0.612)

varying vec2 vTexCoord;

uniform float time;
uniform vec2 resolution;
uniform vec3 u_col;

vec3 color;

vec2 mainPoint;
float voronoiStrength = 0.02;
float pi = acos(-1.0);

vec2 random2d2d(vec2 p){
    return fract(sin(vec2(dot(p.xy,vec2(12.532,95.235)), dot(p.xy,vec2(42.532,65.235))))*24627.1245);
}

float random(vec3 v) { 
	return fract(sin(dot(v, vec3(12.9898, 78.233, 19.8321))) * 43758.5453);
}

float valueNoise(vec3 v) {
	vec3 i = floor(v);
	vec3 f = smoothstep(0.0, 1.0, fract(v));
	return  mix(
		mix(
			mix(random(i), random(i + vec3(1.0, 0.0, 0.0)), f.x),
			mix(random(i + vec3(0.0, 1.0, 0.0)), random(i + vec3(1.0, 1.0, 0.0)), f.x),
			f.y
		),
		mix(
			mix(random(i + vec3(0.0, 0.0, 1.0)), random(i + vec3(1.0, 0.0, 1.0)), f.x),
			mix(random(i + vec3(0.0, 1.0, 1.0)), random(i + vec3(1.0, 1.0, 1.0)), f.x),
			f.y
		),
		f.z
	);
}

float fbm(vec3 v) {
	float n = 0.0;
	float a = 0.5;
	for (int i = 0; i < 5; i++) {
		n += a * valueNoise(v);
		v *= 2.0;
		a *= 0.5;
	}
	return n;
}

vec3 voronoi(vec2 uv, float s)
{
    vec2 uv2 = uv * s;

    vec2 iPos= floor(uv2);
    vec2 fPos = fract(uv2);

    vec3 returnParam = vec3(0.0);
    float dist = 999.0;
    vec2 point = vec2(8.0);
    vec2 offset = vec2(8.0);
    vec2 diff = vec2(8.0);
    for(int y = -1; y <= 1; y++){
        for(int x = -1 ; x <= 1; x++){
            vec2 o = vec2(float(x), float(y));
            vec2 p = random2d2d(iPos + o);

            vec2 di = o + p - fPos;
            float d = dot(di, di);

            point = mix(point, p, (1.0 - step(dist, d)));
            offset = mix(offset, o, (1.0 - step(dist, d)));
            diff = mix(diff, di, (1.0 - step(dist, d)));
            dist = mix(dist, d, (1.0 - step(dist, d)));
        }
    }

    dist = 999.0;
    for(int y = -2; y <= 2; y++){
        for(int x = -2 ; x <= 2; x++){
            vec2 o = offset + vec2(float(x), float(y));
            vec2 p = random2d2d(iPos + o);

            vec2 di = o + p - fPos;

            dist = mix(dist, min(dist, dot(0.5*(diff+di), normalize(di-diff))), (1.0 - step(dot(diff-di, diff-di), 0.0001)));
        }
    }

    mainPoint = point;
    returnParam = vec3(dist, diff);

    return returnParam;
}


vec3 renderingFunc(vec2 uv){
    vec3 color = vec3(0.0);

    float inv = 1.0 / length(uv);
    vec2 uv2 = uv * inv * 0.5 - vec2(inv * 0.5 + time * 0.5);
    color += COLOR_N * 0.3;
    color += 1.0 * voronoiStrength/voronoi(uv2, 4.0).x * COLOR_N;
    color += 0.6 * voronoiStrength/voronoi(uv2 + vec2(10.0, 10.0), 4.0).x * COLOR_T;
    color += 0.6 * voronoiStrength/voronoi(uv2 + vec2(10.0, -10.0), 4.0).x * COLOR_M;
    color += 0.6 * voronoiStrength/voronoi(uv2 + vec2(-10.0, 10.0), 4.0).x * COLOR_K;
    color += 0.6 * voronoiStrength/voronoi(uv2 + vec2(-10.0, -10.0), 4.0).x * COLOR_H;

    color += 0.12 / length(uv);


    return color;
}

void main(){
    vec2 uv = vTexCoord;
	uv.y = 1.0 - uv.y;
	vec2 uv2 = (uv - 0.5) * 2.0;
    vec3 color = vec3(0.0);

    color += renderingFunc(uv2) * u_col;
	float alpha = (color.r + color.g + color.b) / 3.0;

    gl_FragColor = vec4(color, alpha + 0.1);
}
`;

let ps;

let useShader;
let cps;

function setup() {
	// createCanvas(windowWidth, windowHeight);
	createCanvas(1112, 834, WEBGL);
	background(40);
	pixelDensity(1);

	useShader = createShader(vs, fs);
	gl = this._renderer.GL;

	cps = new CardParticleSystem();
}

function draw() {
	background(40);
	gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
	gl.disable(gl.DEPTH_TEST);

	if(random(1) > 0.5){
		cps.addCard();
	}
	cps.updateAndDisplay();

}

function CardParticleSystem()
{
	this.cards = [];

	this.updateAndDisplay = function(){
		for(let i = this.cards.length-1; i >= 0; i--){
			this.cards[i].update();
			this.cards[i].display();
			if(this.cards[i].finished()){
				this.cards.splice(i, 1);
			}
		}
	}

	this.addCard = function(){
		this.cards.push(new ShaderCard());
	}
}

function ShaderCard()
{
	// this.pos = createVector(random(-width*0.5, width*0.5), random(-height*2.0, height*2.0), random(-width, width));
	this.pos = createVector(random(-width*0.5, width*0.5), random(-height*0.5, height*0.5), random(-width, width));
	this.vel = createVector(0.0, 0.0, random(1.0, 10.0));
	this.w = random(40, 300);
	this.h = random(20, 300);
	this.startW = 5;
	this.startH = 5;
	this.currentW = this.startW;
	this.currentH = this.startH;
	this.currentSW = 10;
	this.seed = random(10000);
	this.timeSpeed = random(-0.05, 0.05);
	this.col = [random(1.0), random(1.0), random(1.0)];
	this.timer = 0.0;
	this.isFinish = false;

	this.update = function(){
		this.pos.add(this.vel);
		this.timer += 1.0 / 20.0;
		let number = floor(this.timer);
		let f = fract(this.timer);
		switch(number){
			case 0:{
				this.currentW = lerp(this.startW, this.w, easeInOutExpo(f));
			}break;
			case 1:{
				this.currentH = lerp(this.startH, this.h, easeInOutExpo(f));
			}break;
			case 2:
				break;
			case 3:
				break;
			case 4:{
				this.currentW = lerp(this.w, 0, easeInOutExpo(f));
				this.currentH = lerp(this.h, 0, easeInOutExpo(f));
				this.currentSW = lerp(10, 0, easeInOutExpo(f));
			}break;
			case 5:{
				this.isFinish = true;
			}break;
			default:{

			}
		}
	}

	this.display = function(){
		push();
		translate(this.pos.x, this.pos.y, this.pos.z);
		rectMode(CENTER);
		strokeWeight(this.currentSW);
		stroke(255);
		noFill();
		rect(0, 0, this.currentW, this.currentH);
		noStroke();
		fill(0, 0, 255, 255);
		shader(useShader);
		useShader.setUniform("time", frameCount*this.timeSpeed + this.seed);
		useShader.setUniform("resolution", [this.w, this.h]);
		useShader.setUniform("u_col", this.col);
		plane(this.currentW, this.currentH);
		resetShader();
		pop();
	}

	this.finished = function(){
		return this.isFinish;
	}
}

function easeInOutExpo(x) {
	return x === 0
	  ? 0
	  : x === 1
		? 1
		: x < 0.5
		  ? pow(2, 20 * x - 10) / 2
		  : (2 - pow(2, -20 * x + 10)) / 2;
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
    lapse = millis();
  } 
}

